/* InstanceManager */
CREATE   TRIGGER [dbo].[TR_Audit_Units_0107E443EEEA]
ON [dbo].[Units]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @operation varchar(6) =
        CASE
            WHEN EXISTS (SELECT 1 FROM inserted)
             AND EXISTS (SELECT 1 FROM deleted) THEN 'UPDATE'
            WHEN EXISTS (SELECT 1 FROM inserted) THEN 'INSERT'
            ELSE 'DELETE'
        END;
    DECLARE @before nvarchar(max) = NULL;
    DECLARE @after nvarchar(max) = NULL;

    IF EXISTS (SELECT 1 FROM deleted)
        SELECT @before = (
            SELECT d.[cd_unit] AS [cd_unit], d.[nm_unit] AS [nm_unit], d.[nm_description] AS [nm_description], d.[nr_production] AS [nr_production], d.[nr_batch] AS [nr_batch], d.[cd_product] AS [cd_product], d.[cd_silo] AS [cd_silo], d.[cd_silo_alt] AS [cd_silo_alt], d.[cd_location] AS [cd_location], d.[vl_status] AS [vl_status], d.[vl_unit_type] AS [vl_unit_type], d.[vl_unit_function] AS [vl_unit_function], d.[tp_first_unit_in_location] AS [tp_first_unit_in_location], d.[cd_plc_number] AS [cd_plc_number], d.[vl_db_command] AS [vl_db_command], d.[vl_word] AS [vl_word], d.[vl_db_status] AS [vl_db_status], d.[vl_index_plc] AS [vl_index_plc], d.[vl_empty_time] AS [vl_empty_time], d.[vl_max_discharge_time] AS [vl_max_discharge_time], d.[tp_last_command] AS [tp_last_command], d.[ds_host_ip] AS [ds_host_ip], d.[cd_road] AS [cd_road], d.[vl_road_empty_time] AS [vl_road_empty_time], d.[cd_line] AS [cd_line]
            FROM deleted AS d
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

    IF EXISTS (SELECT 1 FROM inserted)
        SELECT @after = (
            SELECT i.[cd_unit] AS [cd_unit], i.[nm_unit] AS [nm_unit], i.[nm_description] AS [nm_description], i.[nr_production] AS [nr_production], i.[nr_batch] AS [nr_batch], i.[cd_product] AS [cd_product], i.[cd_silo] AS [cd_silo], i.[cd_silo_alt] AS [cd_silo_alt], i.[cd_location] AS [cd_location], i.[vl_status] AS [vl_status], i.[vl_unit_type] AS [vl_unit_type], i.[vl_unit_function] AS [vl_unit_function], i.[tp_first_unit_in_location] AS [tp_first_unit_in_location], i.[cd_plc_number] AS [cd_plc_number], i.[vl_db_command] AS [vl_db_command], i.[vl_word] AS [vl_word], i.[vl_db_status] AS [vl_db_status], i.[vl_index_plc] AS [vl_index_plc], i.[vl_empty_time] AS [vl_empty_time], i.[vl_max_discharge_time] AS [vl_max_discharge_time], i.[tp_last_command] AS [tp_last_command], i.[ds_host_ip] AS [ds_host_ip], i.[cd_road] AS [cd_road], i.[vl_road_empty_time] AS [vl_road_empty_time], i.[cd_line] AS [cd_line]
            FROM inserted AS i
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

    INSERT InstanceManagerAudit.AuditLog
    (
        SchemaName, TableName, Operation, LoginName,
        OriginalLoginName, HostName, ApplicationName,
        SessionId, BeforeData, AfterData
    )
    VALUES
    (
        N'dbo', N'Units', @operation,
        SUSER_SNAME(), ORIGINAL_LOGIN(), HOST_NAME(), APP_NAME(),
        @@SPID, @before, @after
    );
END;
